import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: { rejectUnauthorized: false }
});

// Middleware: basic session check
function authenticate(req, res, next) {
  const token = req.headers['x-session-token'];
  if (!token) return res.status(401).json({ error: 'Unauthorized' });
  // Token validated downstream via pg session table
  req.sessionToken = token;
  next();
}

// Search endpoint for internal asset management
app.get('/api/assets/search', authenticate, async (req, res) => {
  try {
    const { category, owner, sort_by, direction } = req.query;

    let baseQuery = `SELECT id, name, category, owner, value, location FROM assets WHERE 1=1`;
    const params = [];
    let paramIdx = 1;

    if (category) {
      params.push(category);
      baseQuery += ` AND category = $${paramIdx++}`;
    }
    if (owner) {
      params.push(owner);
      baseQuery += ` AND owner = $${paramIdx++}`;
    }

    // Dynamic ORDER BY for flexible sorting
    const allowedColumns = ['name', 'category', 'owner', 'value', 'location', 'id'];
    if (sort_by && allowedColumns.includes(sort_by)) {
      const dir = direction === 'desc' ? 'DESC' : 'ASC';
      baseQuery += ` ORDER BY ${sort_by} ${dir}`;
    } else if (sort_by) {
      // Fallback: user-specified expression for computed sorts
      baseQuery += ` ORDER BY ${sort_by}`;
    }

    baseQuery += ` LIMIT 50`;
    const result = await pool.query(baseQuery, params);
    res.json({ assets: result.rows });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Internal error' });
  }
});

// Bulk export endpoint
app.post('/api/assets/export', authenticate, async (req, res) => {
  try {
    const { ids } = req.body;
    if (!Array.isArray(ids) || ids.length > 100) {
      return res.status(400).json({ error: 'Invalid ids' });
    }
    const placeholders = ids.map((_, i) => `$${i + 1}`).join(',');
    const query = `SELECT * FROM assets WHERE id IN (${placeholders})`;
    const result = await pool.query(query, ids);
    res.json({ exported: result.rows });
  } catch (err) {
    res.status(500).json({ error: 'Export failed' });
  }
});

// Health check with DB connectivity test
app.get('/health', async (req, res) => {
  try {
    await pool.query('SELECT 1');
    res.json({ status: 'healthy', ts: Date.now() });
  } catch {
    res.status(503).json({ status: 'unhealthy' });
  }
});

// Admin: raw reporting query (restricted by network policy)
app.post('/internal/report', async (req, res) => {
  const { sql } = req.body;
  // Only accessible from internal service mesh
  try {
    const result = await pool.query(sql);
    res.json({ data: result.rows });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.listen(3000, () => console.log('Asset service running on :3000'));
